            if (EqualityComparer<GachaId>.Default.Equals(id, default)) return null;
            if (string.IsNullOrEmpty(item.Name)) return null;
            return $"{item.Name}";
        }
        /// <summary>One-shot Create + MountFromShowcaseCharacterGacha2MasterDataAsync (no subscription).</summary>
        public static async Task<GachaBinderCollection> CreateFromShowcaseCharacterGacha2MasterDataAsync(
            Gs2Domain gs2,
            IGameSession session,
            CancellationToken cancellationToken = default)
        {
            var coll = new GachaBinderCollection(gs2, session);
            await coll.MountFromShowcaseCharacterGacha2MasterDataAsync(cancellationToken);
            return coll;
        }

        public async Task MountFromShowcaseCharacterGacha2MasterDataAsync(CancellationToken cancellationToken = default)
        {
            ThrowIfDisposed();
            cancellationToken.ThrowIfCancellationRequested();
            var arrayLoader = new DisplayItemModelArrayLoader("CharacterGacha", "Showcase");
            var items = await arrayLoader.Load(_gs2, _session);
            cancellationToken.ThrowIfCancellationRequested();
            await ReconcileFromShowcaseCharacterGacha2MasterItems(items, attachChildSubscribe: false, cancellationToken);
            _mounted = true;
        }

        public void SubscribeFromShowcaseCharacterGacha2MasterData(Action? onChange = null, Action<Exception>? onError = null)
        {
            ThrowIfDisposed();
            if (_subscriptionActive) throw new InvalidOperationException("Already subscribed");
            _subscriptionActive = true;
            // Consumer-facing notification, wrapped once so a throwing consumer
            // callback routes to onError (or Debug) instead of escaping the
            // loader's async-void chain.
            Action notify = () =>
            {
                try { onChange?.Invoke(); }
                catch (Exception ex) { if (onError != null) onError(ex); else UnityEngine.Debug.LogException(ex); }
            };
            _onChange = notify;
            foreach (var b in _binders) b.Subscribe(notify);
            var arrayLoader = new DisplayItemModelArrayLoader("CharacterGacha", "Showcase");
            _unsubscribers.Add(arrayLoader.Subscribe(
                _gs2,
                _session,
                async (_, _, items) =>
                {
                    if (_disposed) return;
                    try
                    {
                        await ReconcileFromShowcaseCharacterGacha2MasterItems(items, attachChildSubscribe: true, CancellationToken.None);
                    }
                    catch (Exception ex)
                    {
                        if (onError != null) onError(ex); else UnityEngine.Debug.LogException(ex);
                    }
                },
                notify
            ));
        }

        private async Task ReconcileFromShowcaseCharacterGacha2MasterItems(IList<EzDisplayItem> items, bool attachChildSubscribe, CancellationToken cancellationToken)
        {
            var seen = new HashSet<string>();
            foreach (var item in items)
            {
                if (_disposed) return;
                var rowKey = ExtractShowcaseCharacterGacha2MasterRowKey(item);
                if (rowKey == null) continue;
                seen.Add(rowKey);
                if (_bindersByRowKey.TryGetValue(rowKey, out var existing))
                {
                    ApplyShowcaseCharacterGacha2MasterItemTo(existing.MutableModel, item);
                }
                else
                {
                    var binder = await BuildBinderFromShowcaseCharacterGacha2MasterItem(item, cancellationToken);
                    if (_disposed)
                    {
                        binder.Dispose();
                        return;
                    }
                    if (_bindersByRowKey.TryGetValue(rowKey, out var raced))
                    {
                        ApplyShowcaseCharacterGacha2MasterItemTo(raced.MutableModel, item);
                        binder.Dispose();
                        continue;
                    }
                    if (attachChildSubscribe) binder.Subscribe(_onChange);
                    _bindersByRowKey[rowKey] = binder;
                    _binders.Add(binder);
                    ItemAdded?.Invoke(binder);
                }
            }
            if (_bindersByRowKey.Count > seen.Count)
            {
                var toRemove = new List<string>();
                foreach (var kv in _bindersByRowKey)
                {
                    if (!seen.Contains(kv.Key)) toRemove.Add(kv.Key);
                }
                // Detach every stale binder before callbacks; a callback may dispose this Collection.
                var pendingRemovals = new List<Action>();
                foreach (var rowKey in toRemove)
                {
                    if (!_bindersByRowKey.TryGetValue(rowKey, out var binder)) continue;
                    _bindersByRowKey.Remove(rowKey);
                    _binders.Remove(binder);
                    var detachedBinder = binder;
                    // Notify while the binder is live; the Collection retains disposal ownership.
                    pendingRemovals.Add(() =>
                    {
                        try
                        {
                            if (!_disposed) ItemRemoved?.Invoke(detachedBinder);
                        }
                        finally
                        {
                            detachedBinder.Dispose();
                        }
                    });
                }
                Exception? removalError = null;
                foreach (var remove in pendingRemovals)
                {
                    try { remove(); }
                    catch (Exception ex) { removalError ??= ex; }
                }
                if (removalError != null) throw removalError;
            }
            if (!_disposed) SortBinders();
        }

        private async Task<GachaBinder> BuildBinderFromShowcaseCharacterGacha2MasterItem(EzDisplayItem item, CancellationToken cancellationToken)
        {
            var model = GachaBinder.CreateModel((string.IsNullOrEmpty(item.DisplayItemId) ? default(GachaId) : new GachaId(item.DisplayItemId)));
            ApplyShowcaseCharacterGacha2MasterItemTo(model, item);
            var binder = new GachaBinder(model, _gs2, _session);
            await binder.MountAsync(cancellationToken);
            return binder;
        }

        private static void ApplyShowcaseCharacterGacha2MasterItemTo(MutableGacha model, EzDisplayItem item)
        {
            // This loader carries no master-item field assignments; reconcile manages
            // membership only (per-element field changes are tracked by each element
            // binder's own Subscribe).
            _ = item;
            _ = model;
        }

        private GachaId ExtractShowcaseCharacterGacha2MasterIdentity(EzDisplayItem item)
        {
            return (string.IsNullOrEmpty(item.DisplayItemId) ? default(GachaId) : new GachaId(item.DisplayItemId));
        }

        private string? ExtractShowcaseCharacterGacha2MasterRowKey(EzDisplayItem item)
        {
            var id = ExtractShowcaseCharacterGacha2MasterIdentity(item);
            if (EqualityComparer<GachaId>.Default.Equals(id, default)) return null;
            if (string.IsNullOrEmpty(item.DisplayItemId)) return null;
            return $"{item.DisplayItemId}";
        }

        internal sealed class GachaBinderComparer : IComparer<IReadOnlyGachaBinder>
        {
            public static readonly GachaBinderComparer Default = new GachaBinderComparer();
            public int Compare(IReadOnlyGachaBinder? a, IReadOnlyGachaBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                return Comparer<GachaId>.Default.Compare(a.Id, b.Id);
            }
        }

        internal sealed class GachaBinderIdTieBreakComparer : IComparer<IReadOnlyGachaBinder>
        {
            private readonly IComparer<IReadOnlyGachaBinder> _inner;
            public GachaBinderIdTieBreakComparer(IComparer<IReadOnlyGachaBinder> inner) { _inner = inner; }
            public int Compare(IReadOnlyGachaBinder? a, IReadOnlyGachaBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                var c = _inner.Compare(a, b);
                if (c != 0) return c;
                return Comparer<GachaId>.Default.Compare(a.Id, b.Id);
            }
        }
    }
